import { tick } from 'svelte';
import { modalStateRune } from '$lib/stores/modalState.svelte';
import { gameModeService } from './gameModeService';
import { logService } from "./logService.svelte";
import type { Direction } from '$lib/utils/gameUtils';
import { navigationService } from './navigationService';
import type { GameModePreset } from '$lib/stores/gameSettingsTypes';
import { gameSettingsState } from '$lib/stores/gameSettingsState.svelte';
import { endGameService } from './endGameService';
import { boardState } from '$lib/stores/boardState.svelte';
import { playerState } from '$lib/stores/playerState.svelte';
import { scoreState } from '$lib/stores/scoreState.svelte';
import { uiState } from '$lib/stores/uiState.svelte';
import { gameService } from './gameService';
import ReplayViewer from '$lib/components/ReplayViewer.svelte';
import { gameEventBus } from './gameEventBus';
import { modalService } from './modalService';
import { navigateToGame } from './uiService';

let lastMoveTimestamp: number = 0;
const MOVE_COOLDOWN_MS = 250; // Чверть секунди для запобігання деренчанню

/**
 * Режим, у якому «продовжити» й «завершити» — це ГОЛОСИ, а не рішення.
 *
 * Такий лише онлайн: локально рішення виконується одразу. Оголошувати ці методи
 * на `BaseGameMode` не можна — вони існують не в кожному режимі.
 *
 * Доти замість цієї сторожі стояло `'voteToContinue' in activeGameMode` під
 * `@ts-ignore`. Оператор `in` звужує до `BaseGameMode & Record<'voteToContinue',
 * unknown>` — тобто до значення, яке НЕ можна викликати, і саме цю помилку
 * пригнічував коментар. Разом із нею він пригнічував і те, що `voteToFinish`
 * викликався без обовʼязкового для нього аргументу.
 */
interface VotingGameMode {
  voteToContinue(): Promise<void>;
  voteToFinish(reasonKey?: string): Promise<void>;
}

function canVote(mode: unknown): mode is VotingGameMode {
  const candidate = mode as Partial<VotingGameMode> | null;
  return (
    !!candidate &&
    typeof candidate.voteToContinue === 'function' &&
    typeof candidate.voteToFinish === 'function'
  );
}

export const userActionService = {
  selectDirection(direction: Direction): void {
    const uState = uiState.state;
    // FIX: Блокуємо вибір, якщо гра завершена або йде хід
    if (uState?.isGameOver || uState?.isComputerMoveInProgress) return;

    logService.logicMove(`[userActionService] setDirection called with: ${direction}`);
    // DIAGNOSTIC: Log stack trace to find source of call
    console.groupCollapsed(`[userActionService] setDirection trace for ${direction}`);
    console.trace();
    console.groupEnd();

    const bState = boardState.state;
    if (!uState || !bState) return;

    const { boardSize } = bState;
    const { selectedDirection, selectedDistance } = uState;
    const maxDist = boardSize - 1;
    let newDistance = selectedDistance;

    if (selectedDirection !== direction) {
      newDistance = 1;
    } else {
      newDistance = (!selectedDistance || selectedDistance >= maxDist) ? 1 : selectedDistance + 1;
    }

    uiState.update(s => ({ ...s, selectedDirection: direction, selectedDistance: newDistance }));
  },

  selectDistance(distance: number): void {
    const uState = uiState.state;
    // FIX: Блокуємо вибір, якщо гра завершена
    if (uState?.isGameOver) return;

    logService.logicMove(`[userActionService] setDistance called with: ${distance}`);
    uiState.update(s => ({ ...s, selectedDistance: distance }));
  },

  confirmMove(): void {
    const uState = uiState.state;
    // FIX: Блокуємо підтвердження, якщо гра завершена
    if (uState?.isGameOver) return;

    if (uState?.selectedDirection && uState?.selectedDistance) {
      this.executeMove(uState.selectedDirection, uState.selectedDistance);
    }
  },

  async executeMove(direction: Direction, distance: number): Promise<void> {
    const uState = uiState.state;
    // FIX: Блокуємо виконання, якщо гра завершена або йде хід комп'ютера
    if (uState?.isComputerMoveInProgress || uState?.isGameOver) return;

    // СИСТЕМНИЙ ЗАХИСТ: Запобігаємо занадто швидким повторним ходам (деренчання)
    // ВИМИКАЄМО cooldown під час тестів, щоб не флакали E2E тести
    const now = Date.now();
    const isTestMode = typeof window !== 'undefined' && ((window as any).__playwright_test__ || import.meta.env.MODE === 'test');

    if (!isTestMode && (now - lastMoveTimestamp < MOVE_COOLDOWN_MS)) {
      logService.error('[userActionService] executeMove blocked: too soon after last move.');
      return;
    }
    lastMoveTimestamp = now;

    // DIAGNOSTIC: Log stack trace to find source of call
    console.groupCollapsed(`[userActionService] executeMove trace for ${direction} ${distance}`);
    console.trace();
    console.groupEnd();

    // FIX: Скидання вибору прибрано звідси — воно відбувається атомарно
    // всередині handlePlayerMove. Подвійне скидання викликало зайвий рендер
    // і мигання кнопок через CSS transition.
    const activeGameMode = gameModeService.getCurrentMode();
    if (activeGameMode) {
      await activeGameMode.handlePlayerMove(direction, distance);
    }
  },

  async claimNoMoves(): Promise<void> {
    const uState = uiState.state;
    // FIX: Блокуємо дію, якщо гра завершена
    if (uState?.isComputerMoveInProgress || uState?.isGameOver) return;

    const activeGameMode = gameModeService.getCurrentMode();
    if (activeGameMode) {
      await activeGameMode.claimNoMoves();
    }
  },

  async changeBoardSize(newSize: number): Promise<void> {
    const bState = boardState.state;
    const pState = playerState.state;
    const sState = scoreState.state;
    if (!bState || !pState || !sState) return;

    const score = pState.players.reduce((acc: number, p: { score: number }) => acc + p.score, 0);
    if (newSize === bState.boardSize) return;

    if (score === 0 && sState.penaltyPoints === 0) {
      const activeGameMode = gameModeService.getCurrentMode();
      if (activeGameMode) {
        activeGameMode.restartGame({ newSize });
      } else {
        gameService.initializeNewGame({ size: newSize });
      }
      gameSettingsState.updateSettings({ boardSize: newSize });
    } else {
      modalService.showBoardResizeModal(newSize);
    }
  },

  async requestRestart(): Promise<void> {
    modalStateRune.closeModal();

    const currentMode = gameModeService.getCurrentMode();
    const currentModeName = currentMode?.getModeName();

    if (currentModeName === 'online') {
      logService.action('[userActionService] Online mode detected. Skipping local restart logic. Waiting for OnlineGameMode handler.');
      return;
    }

    if (currentModeName === 'local') {
      gameModeService.initializeGameMode('local', false);
    } else {
      const settings = gameSettingsState.state;
      if (settings.gameMode) {
        gameModeService.initializeGameMode(settings.gameMode, false);
      } else {
        if (currentMode) {
          currentMode.restartGame();
        } else {
          logService.state('ERROR: [userActionService] requestRestart called without an active game mode or setting.');
          const currentBoardSize = boardState.state?.boardSize;
          gameService.initializeNewGame({ size: currentBoardSize });
        }
      }
    }
  },

  async requestRestartWithSize(newSize: number): Promise<void> {
    modalStateRune.closeModal();
    const activeGameMode = gameModeService.getCurrentMode();
    if (activeGameMode) {
      activeGameMode.restartGame({ newSize });
    } else {
      gameService.initializeNewGame({ size: newSize });
    }
    gameSettingsState.updateSettings({ boardSize: newSize });
  },

  async requestReplay(): Promise<void> {
    const bState = boardState.state;
    if (!bState) return;
    const { moveHistory, boardSize } = bState;

    modalStateRune.showModal({
      component: ReplayViewer,
      variant: 'menu', // FIX
      buttons: [], // FIX
      props: {
        moveHistory,
        boardSize,
        autoPlayForward: true,
        onClose: () => gameEventBus.dispatch('CloseModal') // Передаємо колбек
      },
      dataTestId: 'replay-modal',
    });
  },

  async finishWithBonus(reasonKey: string): Promise<void> {
    // FIX: Перевірка на завершення гри тут теж корисна, хоча основний захист в endGameService
    if (uiState.state.isGameOver) return;

    logService.logicMove('[userActionService] finishWithBonus called with reason:', reasonKey);
    await endGameService.endGame(reasonKey);
  },

  async continueAfterNoMoves(): Promise<void> {
    const activeGameMode = gameModeService.getCurrentMode();
    if (activeGameMode) {
      await activeGameMode.continueAfterNoMoves();
    }
  },

  // --- Нові методи для голосування ---

  async voteToContinue(): Promise<void> {
    const activeGameMode = gameModeService.getCurrentMode();
    if (canVote(activeGameMode)) {
      await activeGameMode.voteToContinue();
    } else {
      // Локальний режим - просто продовжуємо
      await this.continueAfterNoMoves();
    }
  },

  async voteToFinish(reasonKey: string): Promise<void> {
    const activeGameMode = gameModeService.getCurrentMode();
    if (canVote(activeGameMode)) {
      // `reasonKey` тепер доїжджає до режиму. Доти виклик ішов без аргументів
      // під `@ts-ignore`, тож підпис методу й місце виклику розходилися, і
      // компілятор про це не казав.
      await activeGameMode.voteToFinish(reasonKey);
    } else {
      // Локальний режим - завершуємо
      await this.finishWithBonus(reasonKey);
    }
  },

  async handleModalAction(action: string, payload?: any): Promise<void> {
    const uState = uiState.state;
    if (uState?.isComputerMoveInProgress) {
      return;
    }
    try {
      logService.logicMove('[userActionService] Input locked: isComputerMoveInProgress=true');
      switch (action) {
        case 'restartGame':
        case 'playAgain':
          await this.requestRestart();
          break;
        case 'requestReplay':
          await this.requestReplay();
          break;
        case 'finishWithBonus':
          // Використовуємо новий метод голосування
          await this.voteToFinish(payload.reasonKey);
          break;
        case 'continueAfterNoMoves':
          // Використовуємо новий метод голосування
          await this.voteToContinue();
          break;
        case 'resetGame': {
          const activeGameMode = gameModeService.getCurrentMode();
          if (activeGameMode) {
            await activeGameMode.restartGame({ newSize: payload.newSize });
          }
          gameEventBus.dispatch('CloseModal');
          break;
        }
        case 'closeModal':
          gameEventBus.dispatch('CloseModal');
          break;
        default:
          logService.logicMove(`[userActionService.handleModalAction] Unknown action: ${action}`);
          break;
      }
    } finally {
      await tick();
      logService.logicMove('[userActionService] Input unlocked: isMoveInProgress=false');
    }
  },

  async toggleSpeech(): Promise<void> {
    gameSettingsState.toggleSpeech();
  },

  resetKeybindings(): void {
    gameSettingsState.resetKeybindings();
  },

  setGameModePreset(preset: GameModePreset): void {
    gameSettingsState.applyPreset(preset);
  },

  navigateToGame(): void {
    navigateToGame();
  }
};